def extract(parent):
    raw = base64.b85decode(PAYLOAD)
    if hashlib.sha256(raw).hexdigest() != PAYLOAD_SHA256:
        raise ValueError('Embedded SAR release checksum mismatch')
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        names = set()
        for item in archive.infolist():
            path = PurePosixPath(item.filename)
            if (item.is_dir() or path.is_absolute() or '..' in path.parts
                    or len(path.parts) < 2 or path.parts[0] != 'sar_full_chain_v1'
                    or item.filename in names or ((item.external_attr >> 16) & 0o170000) == 0o120000):
                raise ValueError('Invalid embedded SAR package member')
            names.add(item.filename)
        manifest_name = 'sar_full_chain_v1/RELEASE_SHA256.json'
        manifest = json.loads(archive.read(manifest_name))
        if names != {manifest_name} | {'sar_full_chain_v1/' + name for name in manifest}:
            raise ValueError('Embedded release manifest differs from archive')
        for name, sha in manifest.items():
            if hashlib.sha256(archive.read('sar_full_chain_v1/' + name)).hexdigest() != sha:
                raise ValueError('Embedded file checksum mismatch: ' + name)
        folder = Path(tempfile.mkdtemp(prefix='sar_full_', dir=str(parent)))
        archive.extractall(folder)
    return folder / 'sar_full_chain_v1'


def main(argv=None):
    parser = argparse.ArgumentParser(add_help=False, allow_abbrev=False)
    parser.add_argument('--extract-only', action='store_true')
    args, remaining = parser.parse_known_args(argv)
    tool = extract(Path(__file__).resolve().parent)
    print('TOOL_DIR=' + str(tool), flush=True)
    if args.extract_only:
        print('EXTRACT_ONLY. No training or CUDA context.', flush=True)
        return 0
    command = [sys.executable, '-u', str(tool / 'chain.py'), *remaining]
    env = dict(os.environ, PYTHONDONTWRITEBYTECODE='1', PYTHONUNBUFFERED='1')
    os.execve(sys.executable, command, env)


if __name__ == '__main__':
    raise SystemExit(main())
